module.exports = function(RED) {
    function SwitchNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.name = config.name;
        node.property = config.property;
        node.rules = config.rules || [];

        node.on('input', function(msg) {
            const value = RED.util.getMessageProperty(msg, node.property);
            const outMsgs = new Array(node.rules.length).fill(null);

            for (let i = 0; i < node.rules.length; i++) {
                const rule = node.rules[i];
                const target = Number(rule.v);
                let matched = false;

                switch (rule.t) {
                    case 'eq': matched = (value == target); break;
                    case 'neq': matched = (value != target); break;
                    case 'lt': matched = (value < target); break;
                    case 'lte': matched = (value <= target); break;
                    case 'gt': matched = (value > target); break;
                    case 'gte': matched = (value >= target); break;
                }

                if (matched) {
                    outMsgs[i] = msg;
                }
            }

            node.send(outMsgs);
        });
    }

    RED.nodes.registerType("Switch", SwitchNode);
};